from hermes_tools import terminal
cmd=r'''python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from statistics import median, mean
import math
p='/root/output/result.xlsx'
orig='/root/data/workbook.xlsx'
wb=load_workbook(p, data_only=False)
ws=wb['Task']; ds=wb['Data']
errors=[]
formula_ranges=[(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]
# 1. Formula presence and exact representative pattern checks.
formula_count=0
for r1,r2 in formula_ranges:
    for r in range(r1,r2+1):
        for c in range(8,13):
            v=ws.cell(r,c).value
            formula_count += 1
            if not (isinstance(v,str) and v.startswith('=')):
                errors.append(f'{ws.cell(r,c).coordinate} is not formula: {v!r}')
# 2. Validate lookup formulas and manually calculate lookup values.
years=[ws.cell(10,c).value for c in range(8,13)]
series_data={ds.cell(r,4).value: {ds.cell(4,c).value: ds.cell(r,c).value for c in range(8,13)} for r in range(21,39)}
lookup_spots=['H12','J14','L17','H19','K23','L24','H26','J29','L31']
print('Formula count in required cells:', formula_count)
print('Years H:L:', years)
print('Lookup spot-checks:')
for coord in lookup_spots:
    cell=ws[coord]
    code=ws.cell(cell.row,4).value
    year=ws.cell(10,cell.column).value
    expected=series_data[code][year]
    print(coord, cell.value, '=>', expected)
    if not isinstance(expected,(int,float)):
        errors.append(f'{coord} expected lookup is nonnumeric: {expected!r}')
# 3. Validate expected formula strings for ranges.
for r1,r2 in [(12,17),(19,24),(26,31)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            col=get_column_letter(c)
            exp=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
            if ws.cell(r,c).value != exp:
                errors.append(f'{col}{r} formula mismatch: {ws.cell(r,c).value!r}')
for off,r in enumerate(range(35,41)):
    for c in range(8,13):
        col=get_column_letter(c); exp=f'=({col}{12+off}-{col}{19+off})/{col}{26+off}*100'
        if ws.cell(r,c).value != exp:
            errors.append(f'{col}{r} formula mismatch: {ws.cell(r,c).value!r}')
stat_expect={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE',46:'PERCENTILE25',47:'PERCENTILE75'}
for c in range(8,13):
    col=get_column_letter(c)
    expected_forms={
        42:f'=MIN({col}$35:{col}$40)',
        43:f'=MAX({col}$35:{col}$40)',
        44:f'=MEDIAN({col}$35:{col}$40)',
        45:f'=AVERAGE({col}$35:{col}$40)',
        46:f'=PERCENTILE({col}$35:{col}$40,0.25)',
        47:f'=PERCENTILE({col}$35:{col}$40,0.75)',
        50:f'=SUMPRODUCT({col}$35:{col}$40,{col}$26:{col}$31)/SUM({col}$26:{col}$31)',
    }
    for r,exp in expected_forms.items():
        if ws.cell(r,c).value != exp:
            errors.append(f'{col}{r} formula mismatch: {ws.cell(r,c).value!r}')
# 4. Manual numeric calculation for gap/stat/weighted values.
print('\nManual calculation spot-checks:')
for c in [8,10,12]:
    col=get_column_letter(c); year=ws.cell(10,c).value
    success=[]; failed=[]; cap=[]; gaps=[]
    for off in range(6):
        success.append(series_data[ws.cell(12+off,4).value][year])
        failed.append(series_data[ws.cell(19+off,4).value][year])
        cap.append(series_data[ws.cell(26+off,4).value][year])
        gaps.append((success[-1]-failed[-1])/cap[-1]*100)
    gaps_sorted=sorted(gaps)
    # Excel PERCENTILE.INC equivalent
    def percentile_inc(vals,k):
        vals=sorted(vals); n=len(vals)
        pos=(n-1)*k+1
        if pos==1: return vals[0]
        if pos==n: return vals[-1]
        lower=math.floor(pos); upper=math.ceil(pos); d=pos-lower
        return vals[lower-1] + d*(vals[upper-1]-vals[lower-1])
    weighted=sum(g*w for g,w in zip(gaps,cap))/sum(cap)
    print(col, 'gap first/last=', gaps[0], gaps[-1], 'min=', min(gaps), 'max=', max(gaps), 'median=', median(gaps), 'avg=', mean(gaps), 'p25=', percentile_inc(gaps,0.25), 'p75=', percentile_inc(gaps,0.75), 'weighted=', weighted)
# 5. Style unchanged in edited ranges.
wo=load_workbook(orig, data_only=False)['Task']
for r1,r2 in formula_ranges:
    for r in range(r1,r2+1):
        for c in range(8,13):
            if ws.cell(r,c)._style != wo.cell(r,c)._style:
                errors.append(f'{get_column_letter(c)}{r} style changed')
if errors:
    print('\nVALIDATION FAILED')
    for e in errors[:50]: print(e)
    raise SystemExit(1)
print('\nVALIDATION OK: all required cells contain formulas, formulas reference expected ranges, manual lookup/gap/stat calculations are numeric, styles preserved.')
PY'''
res=terminal(cmd, timeout=60, workdir='/root')
print(res['output'])
if res['exit_code']:
 print('EXIT', res['exit_code'])
